#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/kernel_structs.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define BLK_SIZE 32
#define BLK_ALIGN 4
#define BLK_NUM 4
#define BLK_NUM_MIN 2
#define TIMEOUT K_MSEC(100)

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(tstack1, STACK_SIZE);
static struct k_thread tdata, tdata1;
K_MEM_SLAB_DEFINE(mslab1, BLK_SIZE, BLK_NUM, BLK_ALIGN);
static void *blocks[BLK_NUM];

/*thread entry*/
static void tmslab_alloc_wait_timeout(void *p1, void *p2, void *p3)
{
	void *block;

	/* alloc block with timeout */
	zassert_true(k_mem_slab_alloc(&mslab1, &block, TIMEOUT) == -EAGAIN, NULL);
}

static void tmslab_alloc_wait_ok(void *p1, void *p2, void *p3)
{
	void *block;

	/* alloc block with timeout */
	zassert_ok(k_mem_slab_alloc(&mslab1, &block, TIMEOUT));
	/* free block */
	k_mem_slab_free(&mslab1, &block);
}

static void tmslab_alloc_wait_prio(void *p1, void *p2, void *p3)
{
	void *block;

	/* alloc block */
	zassert_ok(k_mem_slab_alloc(&mslab1, &block, K_FOREVER));
	/* free block */
	k_mem_slab_free(&mslab1, &block);
}

static void mslab_alloc_wait_setup(void)
{
	/* take all blocks */
	for (int i = 0; i < BLK_NUM; i++) {
		zassert_ok(k_mem_slab_alloc(&mslab1, &blocks[i], K_NO_WAIT));
	}
}

/**
 * @brief Test k_mem_slab_alloc with timeout
 *
 * The test creates a thread that will wait for a memory block to be available
 * with a timeout. The test will check if the k_mem_slab_alloc returns
 * -EAGAIN when the block is not available.
 *
 * @ingroup kernel_memory_slab_tests
 *
 * @see k_mem_slab_alloc
 */
ZTEST(mslab_concept, test_mslab_alloc_wait_timeout)
{
	k_tid_t tid = k_thread_create(&tdata, tstack, STACK_SIZE,
				    tmslab_alloc_wait_timeout, NULL, NULL, NULL,
				    K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	/* wait for spawned thread to be done */
	k_thread_join(tid, K_FOREVER);
}

/**
 * @brief Test k_mem_slab_alloc with priority
 *
 * The test creates two threads with different priorities that will wait for a
 * memory block to be available. The test will check if the higher priority
 * thread gets the block first.
 *
 * @ingroup kernel_memory_slab_tests
 *
 * @see k_mem_slab_alloc
 */
ZTEST(mslab_concept, test_mslab_alloc_wait_prio)
{
	/* create low priority thread */
	k_tid_t tid_low = k_thread_create(&tdata, tstack, STACK_SIZE,
					tmslab_alloc_wait_timeout, NULL, NULL, NULL,
					K_PRIO_PREEMPT(1), 0, K_NO_WAIT);

	/* create high priority thread */
	k_tid_t tid_high = k_thread_create(&tdata1, tstack1, STACK_SIZE,
					 tmslab_alloc_wait_prio, NULL, NULL, NULL,
					 K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	/* Let the other threads run and pend on the slab */
	k_sleep(K_MSEC(10));

	/* free a block to unblock high priority thread */
	k_mem_slab_free(&mslab1, &blocks[0]);

	/* wait for spawned threads to be done */
	k_thread_join(tid_high, K_FOREVER);
	k_thread_abort(tid_low);
}

/**
 * @brief Test k_mem_slab_alloc with K_NO_WAIT
 *
 * The test will call k_mem_slab_alloc with K_NO_WAIT and check if it
 * returns -ENOMEM when the block is not available.
 *
 * @ingroup kernel_memory_slab_tests
 *
 * @see k_mem_slab_alloc
 */
ZTEST(mslab_concept, test_mslab_alloc_no_wait)
{
	void *block;

	/* alloc block with no wait */
	zassert_true(k_mem_slab_alloc(&mslab1, &block, K_NO_WAIT) == -ENOMEM,
		     NULL);
}

static void mslab_alloc_wait_teardown(void)
{
	/* free all blocks */
	for (int i = 0; i < BLK_NUM; i++) {
		k_mem_slab_free(&mslab1, &blocks[i]);
	}
}

void *mslab_alloc_wait_setup_new(void)
{
	mslab_alloc_wait_setup();
	return NULL;
}

ZTEST_SUITE(mslab_concept, NULL, mslab_alloc_wait_setup_new,
		mslab_alloc_wait_setup, mslab_alloc_wait_teardown, NULL);
